// safeHTTPClient creates an HTTP client that prevents SSRF attacks by blocking private/internal IPs
func safeHTTPClient() *http.Client {
	return &http.Client{
		Timeout: 3 * time.Second,
		Transport: &http.Transport{
			DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
				// Resolve the address to check for IP-based restrictions
				host, _, err := net.SplitHostPort(addr)
				if err != nil {
					// If no port specified, try parsing as host only
					host = addr
				}

				// Parse the host to get IP addresses
				ips, err := net.LookupIP(host)
				if err != nil {
					return nil, fmt.Errorf("failed to resolve host: %w", err)
				}

				// Check each resolved IP to ensure it's not a private or internal address
				for _, ip := range ips {
					if isPrivateOrInternalIP(ip) {
						return nil, fmt.Errorf("access to private or internal IP addresses is forbidden")
					}
				}

				// Use default dialer if all checks pass
				dialer := &net.Dialer{}
				return dialer.DialContext(ctx, network, addr)
			},
		},
	}
}

// isPrivateOrInternalIP checks if an IP address is private, loopback, or link-local
func isPrivateOrInternalIP(ip net.IP) bool {
	// Check for loopback addresses (127.0.0.1, ::1)
	if ip.IsLoopback() {
		return true
	}

	// Check for private addresses (10.x.x.x, 172.16-31.x.x, 192.168.x.x)
	if ip.IsPrivate() {
		return true
	}

	// Check for link-local addresses (169.254.x.x, fe80::/10)
	if ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
		return true
	}

	// Check for unspecified addresses (0.0.0.0, ::)
	if ip.IsUnspecified() {
		return true
	}

	return false
}

// ConfigureWebhook handles POST requests to configure a webhook URL
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse the JSON request body
	var req webhookRequest
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid JSON format",
		})
	}

	// Validate that webhook_url is provided
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	// Validate URL format
	parsedURL, err := url.ParseRequestURI(req.WebhookURL)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid webhook URL format",
		})
	}

	// Ensure the URL has a valid scheme
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook URL must use http or https scheme",
		})
	}

	// Create a safe HTTP client with timeout and SSRF protection
	client := safeHTTPClient()

	// Prepare test payload
