	"github.com/gofiber/fiber/v2"
)

// WebhookRequest represents the incoming JSON request body
type WebhookRequest struct {
	WebhookURL string `json:"webhook_url"`
}

// WebhookResponse represents the JSON response
type WebhookResponse struct {
	Success bool   `json:"success"`
	Message string `json:"message"`
	URL     string `json:"url,omitempty"`
}

// ConfigureWebhook handles the POST request to configure a webhook URL.
// It validates the webhook URL by sending a GET request with a 3-second timeout,
// then returns a JSON response indicating success or failure.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var req WebhookRequest

	// Parse the JSON body
	if err := ctx.BodyParser(&req); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Success: false,
			Message: "Invalid request body",
		})
	}

	// Validate that webhook_url is provided
	if req.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Success: false,
			Message: "webhook_url is required",
		})
	}

	// Create an HTTP client with a 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Send a GET request to validate the webhook URL
	ctxReq, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()

	reqHTTP, err := http.NewRequestWithContext(ctxReq, http.MethodGet, req.WebhookURL, nil)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(WebhookResponse{
			Success: false,
			Message: fmt.Sprintf("Invalid URL: %s", err.Error()),
		})
	}

	resp, err := client.Do(reqHTTP)
	if err != nil {
		return ctx.Status(fiber.StatusInternalServerError).JSON(WebhookResponse{
			Success: false,
			Message: fmt.Sprintf("Failed to reach webhook URL: %s", err.Error()),
		})
	}
	defer resp.Body.Close()

	// Check if the response status code indicates success (2xx)
	if resp.StatusCode >= 200 && resp.StatusCode < 300 {
		return ctx.Status(fiber.StatusOK).JSON(WebhookResponse{
			Success: true,
			Message: "Webhook configured successfully",
			URL:     req.WebhookURL,
		})
	}

	return ctx.Status(fiber.StatusInternalServerError).JSON(WebhookResponse{
		Success: false,
		Message: fmt.Sprintf("Webhook validation failed with status code: %d", resp.StatusCode),
	})
}

func main() {
	app := fiber.New()

	app.Post("/webhook/configure", ConfigureWebhook)

	fmt.Println("Server starting on :3000")
	if err := app.Listen(":3000"); err != nil {
		fmt.Printf("Error starting server: %v\n", err)
	}
}

