// isPrivateIP checks if an IP address is private or loopback
func isPrivateIP(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
		return true
	}
	return false
}

// safeHTTPClient creates an HTTP client that prevents SSRF by checking resolved IPs
func safeHTTPClient(timeout time.Duration) *http.Client {
	return &http.Client{
		Timeout: timeout,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			// Prevent redirects to avoid bypassing IP check
			return http.ErrUseLastResponse
		},
		Transport: &http.Transport{
			DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
				host, _, err := net.SplitHostPort(addr)
				if err != nil {
					return nil, err
				}

				// Resolve the host to IP addresses
				ips, err := net.LookupIP(host)
				if err != nil {
					return nil, fmt.Errorf("failed to resolve host: %w", err)
				}

				// Check all resolved IPs
				for _, ip := range ips {
					if isPrivateIP(ip) {
						return nil, fmt.Errorf("access to private IP addresses is forbidden")
					}
				}

				// If all IPs are public, proceed with dialing
				dialer := &net.Dialer{}
				return dialer.DialContext(ctx, network, addr)
			},
		},
	}
}

