	"net/http"
	"time"

	"github.com/gofiber/fiber/v2"
)

// WebhookConfig represents the incoming webhook configuration request
type WebhookConfig struct {
	WebhookURL string `json:"webhook_url"`
}

// ConfigureWebhook handles POST requests to configure a webhook URL.
// It validates the URL by sending a GET request with a 3-second timeout,
// then returns a JSON response with the result.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	var config WebhookConfig

	// Parse the JSON body
	if err := ctx.BodyParser(&config); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error":   "Invalid request body",
			"message": err.Error(),
		})
	}

	// Validate that webhook_url is provided
	if config.WebhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error":   "Missing required field",
			"message": "webhook_url is required",
		})
	}

	// Create an HTTP client with a 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	// Send a GET request to validate the webhook URL
	req, err := http.NewRequestWithContext(context.Background(), http.MethodGet, config.WebhookURL, nil)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error":   "Invalid URL",
			"message": fmt.Sprintf("Failed to create request: %v", err),
		})
	}

	resp, err := client.Do(req)
	if err != nil {
		return ctx.Status(fiber.StatusBadGateway).JSON(fiber.Map{
			"error":   "Webhook validation failed",
			"message": fmt.Sprintf("Failed to reach webhook URL: %v", err),
		})
	}
	defer resp.Body.Close()

	// Check if the response status code indicates success (2xx)
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadGateway).JSON(fiber.Map{
			"error":   "Webhook validation failed",
			"message": fmt.Sprintf("Webhook URL returned status code: %d", resp.StatusCode),
		})
	}

	// Simulate saving the configuration (in a real app, this would persist to a database)
	// For now, we just return success

	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"success": true,
		"message": "Webhook configured successfully",
		"data": fiber.Map{
			"webhook_url": config.WebhookURL,
		},
	})
}

func main() {
	app := fiber.New()

	app.Post("/configure-webhook", ConfigureWebhook)

	app.Listen(":3000")
}

