package main

import (
	"net/http"
	"time"

	"github.com/gofiber/fiber/v2"
)

// ConfigureWebhook handles the POST request to configure a webhook URL.
// It validates the webhook URL by sending a GET request with a 3-second timeout,
// then returns a JSON response with the result.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse the JSON body
	var body struct {
		WebhookURL string `json:"webhook_url"`
	}

	if err := ctx.BodyParser(&body); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid JSON body",
		})
	}

	webhookURL := body.WebhookURL
	if webhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "webhook_url is required",
		})
	}

	// Validate the webhook URL by sending a GET request with a 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	req, err := http.NewRequest("GET", webhookURL, nil)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"success": false,
			"error":   "Invalid webhook URL format",
		})
	}

	resp, err := client.Do(req)
	if err != nil {
		return ctx.Status(fiber.StatusServiceUnavailable).JSON(fiber.Map{
			"success": false,
			"error":   "Failed to validate webhook URL: " + err.Error(),
		})
	}
	defer resp.Body.Close()

	// Check if the response status code indicates success (2xx)
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadGateway).JSON(fiber.Map{
			"success": false,
			"error":   "Webhook URL validation failed with status code: " + string(rune(resp.StatusCode)),
		})
	}

	// Save the configuration (in a real application, this would persist to a database or config store)
	// For this example, we just acknowledge successful validation and configuration

	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"success":      true,
		"webhook_url":  webhookURL,
		"message":      "Webhook configured successfully",
	})
}

func main() {
	app := fiber.New()

	app.Post("/configure-webhook", ConfigureWebhook)

	app.Listen(":3000")
}

