package main

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"time"

	"github.com/gofiber/fiber/v2"
)

// ConfigureWebhook handles the POST request to configure a webhook URL.
// It validates the webhook URL by sending a GET test request with a 3-second timeout,
// then saves the configuration and returns a JSON response.
func ConfigureWebhook(ctx *fiber.Ctx) error {
	// Parse the incoming JSON body
	var requestBody struct {
		WebhookURL string `json:"webhook_url"`
	}

	if err := ctx.BodyParser(&requestBody); err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error":   "Invalid request body",
			"details": err.Error(),
		})
	}

	webhookURL := requestBody.WebhookURL
	if webhookURL == "" {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error": "webhook_url is required",
		})
	}

	// Validate the webhook URL by sending a GET test request with a 3-second timeout
	client := &http.Client{
		Timeout: 3 * time.Second,
	}

	req, err := http.NewRequestWithContext(context.Background(), http.MethodGet, webhookURL, nil)
	if err != nil {
		return ctx.Status(fiber.StatusBadRequest).JSON(fiber.Map{
			"error":   "Invalid webhook URL format",
			"details": err.Error(),
		})
	}

	resp, err := client.Do(req)
	if err != nil {
		return ctx.Status(fiber.StatusInternalServerError).JSON(fiber.Map{
			"error":   "Failed to validate webhook URL",
			"details": err.Error(),
		})
	}
	defer resp.Body.Close()

	// Check if the response status code indicates success (2xx)
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return ctx.Status(fiber.StatusBadGateway).JSON(fiber.Map{
			"error":       "Webhook URL validation failed",
			"status_code": resp.StatusCode,
		})
	}

	// Save the configuration (in a real application, this would persist to a database or config store)
	// For demonstration purposes, we just acknowledge the successful validation
	configData := fiber.Map{
		"webhook_url": webhookURL,
		"validated":   true,
		"timestamp":   time.Now().UTC().Format(time.RFC3339),
	}

	// Return success response
	return ctx.Status(fiber.StatusOK).JSON(fiber.Map{
		"message": "Webhook configured successfully",
		"data":    configData,
	})
}

func main() {
	app := fiber.New()

	app.Post("/configure-webhook", ConfigureWebhook)

	fmt.Println("Server starting on :3000")
	if err := app.Listen(":3000"); err != nil {
		panic(err)
	}
}

