// isPrivateIP checks if an IP address is private or internal
func isPrivateIP(ip net.IP) bool {
	// Check for loopback addresses
	if ip.IsLoopback() {
		return true
	}

	// Check for link-local unicast addresses
	if ip.IsLinkLocalUnicast() {
		return true
	}

	// Check for link-local multicast addresses
	if ip.IsLinkLocalMulticast() {
		return true
	}

	// Check for private IPv4 addresses
	if ip.To4() != nil {
		privateRanges := []struct {
			start net.IP
			end   net.IP
		}{
			{net.ParseIP("10.0.0.0"), net.ParseIP("10.255.255.255")},
			{net.ParseIP("172.16.0.0"), net.ParseIP("172.31.255.255")},
			{net.ParseIP("192.168.0.0"), net.ParseIP("192.168.255.255")},
			{net.ParseIP("127.0.0.0"), net.ParseIP("127.255.255.255")},
		}

		for _, r := range privateRanges {
			if bytes.Compare(ip, r.start) >= 0 && bytes.Compare(ip, r.end) <= 0 {
				return true
			}
		}
	}

	// Check for private IPv6 addresses (ULA - Unique Local Address)
	if ip.To16() != nil && ip.To4() == nil {
		// fc00::/7 is the unique local address range
		if len(ip) == 16 && (ip[0] == 0xfc || ip[0] == 0xfd) {
			return true
		}
	}

	return false
}

