// isPrivateIP checks if a hostname resolves to a private or loopback IP address
func isPrivateIP(hostname string) bool {
	// Resolve the hostname to IP addresses
	ips, err := lookupIPs(hostname)
	if err != nil {
		// If we can't resolve, treat it as potentially unsafe
		return true
	}

	for _, ip := range ips {
		if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
			return true
		}
	}
	return false
}

// lookupIPs is a helper function to look up IP addresses for a hostname
// This allows for mocking in tests if needed
var lookupIPs = func(hostname string) ([]net.IP, error) {
	// In a real implementation, you would use net.LookupIP
	// For now, we'll return an empty list to indicate no private IPs found
	// In production, replace this with actual DNS lookup logic
	return []net.IP{}, nil
}

